// Battery Status register
// 185: 电池状态 (Battery Status)
// May contain SOH info from BMS - testing needed

msg.payload = {
    fc: 3,
    unitid: 1,
    address: 185,
    quantity: 1
};

return msg;

// Build BatterySohState from Modbus read.
//
// Register:
// 185: Battery Status (电池状态)
// 
// NOTE: This may not be actual SOH percentage.
// Testing needed to determine what this register contains.
// If value is 0-100, it might be SOH%.
// If value is a bit field, interpretation is different.

let raw = msg.payload;

// node-red-contrib-modbus often sends { data: [...], buffer: ... }
let data = raw;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

// Skip string errors
if (typeof raw === "string" || !Array.isArray(data)) {
    return null;
}

const batteryStatusRaw = data[0] || 0;

// Attempt to interpret as SOH percentage
// If value is 0-100, use it directly
// If value is > 100, might need different interpretation
let sohPercent = null;
if (batteryStatusRaw >= 0 && batteryStatusRaw <= 100) {
    sohPercent = batteryStatusRaw;
} else {
    // Could be a bit field or different scale
    // Store raw value for analysis
    sohPercent = null;
}

// Resolve DeviceId
const deviceId = msg.deviceId
    || global.get("DEVICE_ID")
    || env.get("DEVICE_ID")
    || "EC100-DEV-001";

const state = {
    kind: "BatterySohState",
    timestampUtc: new Date().toISOString(),
    version: 1,
    DeviceId: deviceId,

    // Raw value for debugging
    _rawBatteryStatus: batteryStatusRaw,
    _rawHex: "0x" + batteryStatusRaw.toString(16).padStart(4, '0'),

    // SOH as seen by inverter
    inverterBatChannelSoh: [
        {
            channelId: 1,
            sohPercent: sohPercent
        },
        {
            channelId: 2,
            sohPercent: null  // Reserved for future use
        }
    ],

    // BMS SOH details - would come from separate BMS communication
    // Not available from inverter registers
    bmsSohDetails: []
};

// Keep snapshot in flow
flow.set("batterySohSnapshot", state);

// Put result on msg
msg.payload = state;
msg.state = state;

return msg;
